DROP TABLE IF EXISTS `stock_item_holdings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stock_item_holdings` (
  `StockCode` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `QuantityOnHand` bigint NOT NULL DEFAULT '0',
  `BinLocation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `LastStocktakeQuantity` bigint unsigned NOT NULL DEFAULT '0',
  `LastCostPrice` decimal(18,3) NOT NULL DEFAULT '0.000',
  `ReorderLevel` bigint unsigned NOT NULL DEFAULT '0',
  `TargetStockLevel` bigint unsigned NOT NULL DEFAULT '0',
  `LastEditedBy` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`StockCode`),
  KEY `stock_item_holdings_lasteditedby_foreign` (`LastEditedBy`),
  CONSTRAINT `stock_item_holdings_lasteditedby_foreign` FOREIGN KEY (`LastEditedBy`) REFERENCES `users` (`id`),
  CONSTRAINT `stock_item_holdings_stockcode_foreign` FOREIGN KEY (`StockCode`) REFERENCES `products` (`StockCode`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
